"""GET /orders — N+1 hunt demo.

Two implementations behind one route:
  - mode="naive": 1 query for orders + 1 query per order  -> 51 statements
  - mode="fixed": 1 JOIN, grouped in Python               -> 1 statement

Both produce byte-identical JSON on the seed data.

The sqlite3 connection is wrapped so every executed statement increments a
per-request counter (set_trace_callback fires once per prepared statement).
"""
from __future__ import annotations

import sqlite3
from contextlib import closing

from flask import Flask, g, jsonify


# --------------------------------------------------------------------------- #
# Database
# --------------------------------------------------------------------------- #
def create_db(path: str = ":memory:") -> sqlite3.Connection:
    """Create schema + seed 50 orders x 3 items."""
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    conn.executescript(
        """
        CREATE TABLE orders (id INTEGER PRIMARY KEY, customer TEXT NOT NULL);
        CREATE TABLE order_items (
            id       INTEGER PRIMARY KEY,
            order_id INTEGER NOT NULL REFERENCES orders(id),
            sku      TEXT NOT NULL,
            qty      INTEGER NOT NULL
        );
        """
    )
    orders = [(i, f"customer-{i}") for i in range(1, 51)]
    conn.executemany("INSERT INTO orders VALUES (?, ?)", orders)
    # Insertion order matters for byte-identity: items grouped per order,
    # skus ascending, matching what the naive per-order scans return.
    items = [
        (o_id, f"SKU-{k:03d}", k * 10)
        for o_id, _ in orders
        for k in range(1, 4)
    ]
    conn.executemany("INSERT INTO order_items (order_id, sku, qty) VALUES (?, ?, ?)", items)
    conn.commit()
    return conn


class CountingConnection:
    """Thin wrapper counting SQL statements executed on the real connection."""

    def __init__(self, conn: sqlite3.Connection):
        self._conn = conn
        self.statements: list[str] = []
        conn.set_trace_callback(self.statements.append)

    def execute(self, sql: str, params: tuple = ()):  # type: ignore[assignment]
        return self._conn.execute(sql, params)

    @property
    def statement_count(self) -> int:
        return len(self.statements)


# --------------------------------------------------------------------------- #
# Route implementations
# --------------------------------------------------------------------------- #
def _orders_naive(db: CountingConnection):
    """Original code: one round-trip per order -> N+1."""
    out = []
    for o in db.execute("SELECT id, customer FROM orders").fetchall():
        items = db.execute(
            "SELECT sku, qty FROM order_items WHERE order_id=?", (o["id"],)
        ).fetchall()
        out.append({"id": o["id"], "customer": o["customer"],
                    "items": [dict(i) for i in items]})
    return out


def _orders_fixed(db: CountingConnection):
    """Single JOIN, grouped in Python. Same rows, same order, same shape."""
    rows = db.execute(
        """
        SELECT o.id, o.customer, oi.sku, oi.qty
        FROM orders o
        LEFT JOIN order_items oi ON oi.order_id = o.id
        ORDER BY o.id, oi.id
        """
    ).fetchall()
    out: list[dict] = []
    current: dict | None = None
    for r in rows:
        if current is None or current["id"] != r["id"]:
            current = {"id": r["id"], "customer": r["customer"], "items": []}
            out.append(current)
        current["items"].append({"sku": r["sku"], "qty": r["qty"]})
    return out


IMPLEMENTATIONS = {"naive": _orders_naive, "fixed": _orders_fixed}


def create_app(mode: str = "fixed", db_path: str = ":memory:") -> Flask:
    app = Flask(__name__)
    raw_conn = create_db(db_path)
    app.extensions["db"] = CountingConnection(raw_conn)

    @app.before_request
    def _reset_counter():
        g.query_count_at_start = app.extensions["db"].statement_count

    @app.get("/orders")
    def orders():
        impl = IMPLEMENTATIONS[mode]
        return jsonify(impl(app.extensions["db"]))

    @app.get("/_query_count")
    def query_count():
        db = app.extensions["db"]
        return jsonify(count=db.statement_count - g.query_count_at_start)

    @app.teardown_appcontext
    def _close(exc):
        raw_conn.close()

    return app


if __name__ == "__main__":
    import sys

    create_app(sys.argv[1] if len(sys.argv) > 1 else "fixed").run(port=5000)

